  if(current.mode==='waste'){
   const source=lots.find(l=>l.barcode===code&&(l.location?.area||'Unassigned')===current.area&&(l.location?.shelf||'Unsorted')===current.shelf&&!current.items.some(i=>i.id===l.id));
   if(!source){msg(t('No remaining matching inventory item in this source location. Nothing removed.'));return false;}
   added={...source,pending:false};current.items.push(added);if(operationId)scannerHandoffOperations=[...scannerHandoffOperations,operationId];saveDraft();saved=true;
   renderBasket();displayAccepted(source,products[code]);scanFeedback(products[code]||source);return true;
  }
