function findMeals(){recipeLibrary?.refresh();const target=$('meals');target.replaceChildren();const servings=Number($('servings').value);const inventory=menuInventory();renderDinnerMembers();const diners=(profile.members||[]).filter(m=>!absentDiners.has(m.id));let rows=rankedMenus($('show-review-meals').checked?recipes:recipes.filter(quantified),inventory,products,diners,servings,today());const all=rows;setLocalizedText($('recipe-count'),"{v0} recipes · {v1} quantified · {v2} portions · browse 24 or show all",{v0:(recipes.length),v1:(recipes.filter(quantified).length),v2:(servings)});$('menu-overview').replaceChildren();for(const [label,value]of [['Ready to cook',all.filter(r=>r.status==='ready').length],['Menus to explore',recipes.length],['Items in scope',inventory.length]]){const box=document.createElement('span'),b=document.createElement('b');setLocalizedText(b,value);box.append(b,document.createTextNode(t(label)));$('menu-overview').append(box);}const search=normalizeSearchText($('menu-search').value);const status=$('menu-ready').value;rows=rows.filter(r=>(!status||r.status===status)&&(!search||multilingualSearchText(r).includes(search)));if(!rows.length){const empty=document.createElement('div');empty.className='empty-state';setLocalizedText(empty,'No matching menus yet. Try another ingredient or choose the whole kitchen.');target.append(empty);}for(const r of rows.slice(0,$('show-all-meals').checked?rows.length:search||status?70:24)){const a=document.createElement('article'),badge=document.createElement('span'),title=document.createElement('strong');badge.className='meal-status'+(r.status==='ready'?'':' missing-status');setLocalizedText(badge,r.status==='ready'?t('READY TO COOK'):r.status==='needs_review'?t('REVIEW SOURCE QUANTITIES'):t('INGREDIENTS TO ADD'));showLocalized(title,localizedField(r,'title'));a.append(badge,title);const info=document.createElement('p');setLocalizedText(info,"{v0} portions{v1}",{v0:(servings),v1:(r.time?' · '+r.time:'')});a.append(info);const availability=document.createElement('p');setLocalizedText(availability,r.status==='ready'?t('All measured ingredients are available.'):r.missing.length?t("Missing: {v0}", {v0:(r.missing.map(i=>`${i.quantity} ${i.unit} ${i.ingredient}`).join(', '))}):t('Some original quantities need review.'));if(r.unknown.length)availability.textContent+=t(" · {v0} ingredient quantities need review.", {v0:(r.unknown.length)});a.append(availability);const family=document.createElement('p');family.className='menu-family-status'+(r.group.compatible?'':' conflict');setLocalizedText(family,!diners.length?t('Add household members for personalised menus.'):r.group.compatible?(r.group.checks.length?'Needs checking for the selected diners':'No known ingredient conflict for the selected diners')+(r.group.changes.length?' · '+r.group.changes.join('; '):''):t("Separate meal needed for {v0}", {v0:(r.group.blocked.join(', '))}));if(r.group.checks.length)family.textContent+=t(' · '+[...new Set(r.group.checks)].join('; '));a.append(family);const locations=[...new Set(inventory.filter(l=>r.ingredients.some(i=>normalize(i.ingredient)===normalize(l.ingredient))).map(l=>locationKey(l.location)))];const place=document.createElement('p');place.className='menu-location-note';setLocalizedText(place,locations.length?t("From {v0}", {v0:(locations.join(' · '))}):t('Add matching ingredients to your kitchen.'));a.append(place);const detail=document.createElement('details'),summary=document.createElement('summary');setLocalizedText(summary,'Ingredients, quantities & directions');detail.append(summary);const ingredients=document.createElement('ul');ingredients.className='menu-ingredients';for(const ingredient of r.ingredients){const line=document.createElement('li');const amount=ingredient.quantity==null?'Quantity not specified':displayAmount(ingredient.quantity*servings/r.servings,ingredient.unit,profile.units);setLocalizedText(line,ingredient.raw&&ingredient.quantity==null?t("{v0} · quantity needs review", {v0:(ingredient.raw)}):`${amount} ${displayName(ingredient)}${ingredient.optional?' ('+t('Optional')+')':''}`);const stock=inventory.filter(l=>normalize(l.ingredient)===normalize(ingredient.ingredient)&&!l.needsReview);if(stock.length){const storage=document.createElement('small');setLocalizedText(storage,' — '+[...new Set(stock.map(l=>locationKey(l.location)))].join(', '));line.append(storage);}ingredients.append(line);}detail.append(ingredients);const steps=document.createElement('ol');const instructions=localizedField(r,'instructions');for(const [index,instruction] of instructions.value.entries()){const step=document.createElement('li');showLocalized(step,instructions.items?.[index]||{...instructions,value:instruction});steps.append(step);}detail.append(steps);if(r.ingredients.some(i=>i.raw)){const original=document.createElement('details'),s=document.createElement('summary'),p=document.createElement('p');setLocalizedText(s,'Original ingredient wording');setLocalizedText(p,r.ingredients.map(i=>i.raw||i.ingredient).join('\n'));p.style.whiteSpace='pre-line';original.append(s,p);detail.append(original);}const origin=document.createElement('p');origin.className='recipe-origin';const link=document.createElement('a');setLocalizedText(link,r.source);if(/^https?:\/\//.test(r.source))link.href=r.source;origin.append(link,document.createTextNode(t(' · '+r.license+(r.attribution?' · '+r.attribution:''))));detail.append(origin);a.append(detail);const food=document.createElement('details'),foodSummary=document.createElement('summary'),foodInfo=document.createElement('p');setLocalizedText(foodSummary,'Food data & estimated nutrition');foodInfo.className='recipe-food-data';const data=planSummary([{recipeId:r.id,date:today(),servings}],recipes,inventory,products,[today()]);setLocalizedText(foodInfo,"{v0}\nFor all {v1} portions. Based on allocated ingredient lots with a compatible nutrition basis; brands can differ. Uncovered amounts and missing nutrition remain unknown.",{v0:(NUTRIENTS.map(([key,label,unit])=>{const n=data.totals[key];return `${label}: ${n.known?Number(n.value.toPrecision(3))+' '+unit:'not available'}${n.known&&n.known<n.total?' (partial)':''}`;}).join('\n')),v1:(servings)});foodInfo.style.whiteSpace='pre-line';food.append(foodSummary,foodInfo);a.append(food);const add=document.createElement('button');add.className='coral';setLocalizedText(add,"Add to {v0} menu +",{v0:(new Date($('plan-date').value+'T12:00:00').toLocaleDateString(getLanguage(),{weekday:'short'} ))});add.onclick=()=>{profile.plan||=[];profile.plan.push({id:crypto.randomUUID(),recipeId:r.id,date:$('plan-date').value,slot:$('plan-slot').value,servings,memberIds:diners.map(m=>m.id),adjustments:r.group.changes});localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();renderPlan();setLocalizedText($('menu-notice'),"{v0} added to {v1} {v2}.",{v0:(r.title),v1:($('plan-date').value),v2:($('plan-slot').value.toLowerCase())});};a.append(add);if(quantified(r)){const cook=document.createElement('button');setLocalizedText(cook,'Cook this meal');cook.className='outline';cook.disabled=!r.group.compatible;cook.onclick=()=>journey.openCook(r);a.append(cook);}const select=document.createElement('button');select.className='outline';setLocalizedText(select,selections.includes(r.id)?t('Saved favourite ✓'):t('Save as favourite'));select.onclick=()=>{selections=selections.includes(r.id)?selections.filter(x=>x!==r.id):[...selections,r.id];localStorage.setItem(SELECTIONS,JSON.stringify(selections));markDirty();findMeals();};a.append(select);target.append(a);}renderPlan();}
$('refresh').onclick=()=>{try{findMeals();}catch(e){msg(e.message);}};
$('add').onsubmit=e=>{e.preventDefault();try{if(!canEditCheckout())return;const target=session||lastReceipt;if(!scannerScopeMatches(target))throw Error('Scanner inventory space changed before correction.');if(!target||!editingId)throw Error(t('Choose an item to correct on the final receipt.'));const index=target.items.findIndex(i=>i.id===editingId);if(index<0)throw Error(t('Item no longer on receipt.'));const old=target.items[index],item={...old};for(const key of ['name','ingredient','quantity','unit','expires'])item[key]=$(key).value;item.amountBasis='manual';item.needsReview=item.ingredient==='unmapped';const edited=validateLot(item);target.items[index]=edited;if(session){saveDraft();renderBasket();}else{save(lots.map(i=>i.id===edited.id?{...i,...edited}:i));saveReceipt(lastReceipt);pantry();findMeals();}editingId=null;$('item-review').hidden=true;if(!session){$('checkout-run').hidden=true;$('checkout-complete').hidden=false;}renderFinalReceipt(target,!session);$('finish-dialog').showModal();}catch(e){msg(e.message);}};
let shopsRequest=0;
$('shops').onclick=async()=>{const attempt=++shopsRequest,target=$('prices');target.replaceChildren();setLocalizedText(target,'Checking dated observations…');try{
 const code=$('barcode').value.trim();if(!/^\d{4,32}$/.test(code))throw Error(t('Enter or scan a barcode first.'));
 const {saved,savedError,upstreamError,upstream:v}=await loadPriceObservations({barcode:code,country:profile.country||'',profile,getIdentity:()=>requestIdentity,request:boundFetch});
 if(attempt!==shopsRequest)return;target.replaceChildren();renderSavedPriceObservations(target,saved);
 const rows=v.items;if(!saved.length&&!rows.length)setLocalizedText(target,"No matching observations in the latest sample{v0}. This does not mean no retailer sells it.",{v0:profile.country?' for '+names.of(profile.country):''});
 for(const r of rows)card(target,r.location?.osm_name||r.location?.osm_display_name||'Shop observation #'+r.location_id,`${r.currency} ${r.price} · ${r.date} · ${r.location?.osm_address_country||'country unknown'} · historical observation`);
 if(v.offmenu_stale)card(target,'Cached observations','Refresh unavailable; these are earlier downloaded observations.');
 if(savedError)card(target,'Saved observations unavailable','Some saved observations could not be loaded. Retry in your current profile.');
 if(upstreamError)card(target,'Latest price lookup unavailable','Saved dated observations remain historical.');
}catch(e){if(attempt===shopsRequest)setLocalizedText(target,e.message);}};
function download(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
// The export check uses the same UTF-8, pretty-printed bytes as download().
const PANTRY_BACKUP_MAX_BYTES=20_000_000;
$('export').onclick=()=>{try{const backup=createPantryBackup({inventory:lots,profile,products,recipes,selections},{accountId:user?.id});if(new Blob([JSON.stringify(backup,null,2)]).size>PANTRY_BACKUP_MAX_BYTES)throw Error(t('Pantry backup exceeds 20 MB.'));download('offmenu-pantry.json',backup);}catch(e){msg(e.message);}};
async function readJSON(input,maxBytes=2_000_000){const f=input.files[0];if(!f)return null;if(f.size>maxBytes)throw Error(maxBytes===PANTRY_BACKUP_MAX_BYTES?t('Pantry backup exceeds 20 MB.'):t('File must be under 2 MB.'));return JSON.parse(await f.text());}
$('restore').onchange=async()=>{const started=requestIdentity;try{
 const v=await readJSON($('restore'),PANTRY_BACKUP_MAX_BYTES);if(!v)return;
 if(requestIdentity!==started)throw Error(t('Account changed. Retry from your current account.'));
 const {inventory:next,state}=restorePantryBackup(v,{accountId:user?.id});
 if(lots.length&&!confirm(t('Replace your pantry with this backup?')))return;
 const nextProfile=state?state.profile:{...profile,batches:reconcileCookedStock(profile.batches||[],next,{date:today()})};
 const entries=[[KEY,next],[PROFILE,nextProfile],...(state?[[PRODUCTS,state.products],[RECIPES,state.recipes],[SELECTIONS,state.selections]]:[])].map(([key,value])=>[key,JSON.stringify(value),localStorage.getItem(key)]);
 // Keep memory and sync untouched until every storage write has succeeded.
 const written=[];
 try{for(const entry of entries){localStorage.setItem(entry[0],entry[1]);written.push(entry);}}
 catch(error){let rollbackFailed=false;for(const [key,,previous]of written.reverse()){try{if(previous===null)localStorage.removeItem(key);else localStorage.setItem(key,previous);}catch{rollbackFailed=true;}}if(rollbackFailed)throw Error(t('Backup restore failed and browser storage could not be fully restored. Keep your backup and reload before making changes.'));throw error;}
 lots=next;profile=nextProfile;if(state){products=state.products;recipes=state.recipes;selections=state.selections;}
 markDirty();if(state)loadProfile();pantry();findMeals();msg(t('Backup restored in this browser. Save to cloud to back it up.'));
}catch(e){msg(e.message);}finally{$('restore').value='';}};
$('recipe-import').onchange=async()=>{try{const v=await readJSON($('recipe-import'));if(!v)return;const imported=validateRecipes(v);const next=[...new Map([...recipes,...imported].map(r=>[r.id,r])).values()];localStorage.setItem(RECIPES,JSON.stringify(next));recipes=next;markDirty();findMeals();msg(t('Recipes imported.'));}catch(e){msg(e.message);}finally{$('recipe-import').value='';}};
function connectivity(){setLocalizedText($('connection'),demoMode?t('Demo kitchen · separate sample data.'):navigator.onLine?user?t('Signed in · automatic cloud saves; local copy available offline.'):t('Guest pantry · saved in this browser.'):t('Offline · Pantry and downloaded recipes work. New product and shop lookups need internet.'));}window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);
let applicationDefaults={country:'',units:'metric',servings:2};
async function init(){try{try{const config=await jsonFetch('/api/services');if(config.globalDefaults)applicationDefaults={country:config.globalDefaults.country,units:config.globalDefaults.units,servings:config.globalDefaults.servings};}catch{}await initAuth();loadProfile();lots=JSON.parse(localStorage.getItem(KEY)||'[]').map(validateLot);products=JSON.parse(localStorage.getItem(PRODUCTS)||'{}');const stored=localStorage.getItem(RECIPES);const fresh=await fetchRecipes();recipes=validateRecipes([...new Map([...(stored?JSON.parse(stored):[]),...fresh].map(r=>[r.id,r])).values()]);localStorage.setItem(RECIPES,JSON.stringify(recipes));pantry();findMeals();connectivity();if(!lifecycleFixture&&'serviceWorker'in navigator)await navigator.serviceWorker.register('/sw.js');}catch(e){msg(t("Setup needs attention: {v0}", {v0:(e.message)}));}}
function markDirty(){if(lifecycleFixture){dirty=true;setLocalizedText($('sync-status'),'Synthetic fixture changes saved only in this isolated local namespace.');return;}dirty=true;if(typeof syncReady!=='undefined'&&syncReady){if(sharing.active())sharing.schedule();else autoSync.schedule();}if(user&&!demoMode)localStorage.setItem(KEY+'-dirty','1');setLocalizedText($('sync-status'),demoMode?t('Demo changes stay separate from your kitchen.'):user?t('Local changes · saving automatically.'):t('Guest data is saved in this browser.'));}
function loadProfile(){profile=JSON.parse(localStorage.getItem(PROFILE)||JSON.stringify(applicationDefaults));if(authResolved)applyAccountLanguage({user,profile,isDemo:demoMode,reload:()=>setTimeout(()=>location.reload(),0)});selections=JSON.parse(localStorage.getItem(SELECTIONS)||'[]');for(const link of document.querySelectorAll('a[href^="/data-workspace.html"]'))link.href='/data-workspace.html'+(profile.country?'?country='+encodeURIComponent(profile.country):'');$('country').value=profile.country||'';if(syncReady)journey.applyPreferences();$('units').value=profile.units||'metric';$('servings').value=profile.servings||2;lastReceipt=profile.lastReceipt||null;$('view-last-receipt').hidden=!lastReceipt;feedback={sound:false,vibration:false,screen:false,light:false,speech:false,...profile.feedback};applyFeedbackSettings();}
onLanguagePreference(locale=>{profile={...profile,uiLanguage:locale};localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();services.render();});
function saveProfile(){profile={...profile,country:$('country').value,units:$('units').value,servings:Number($('servings').value)};localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();}
for(const id of ['country','units','servings'])$(id).addEventListener('change',saveProfile);
const names=new Intl.DisplayNames([getLanguage()],{type:'region'});const countries='AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW'.split(' ').map(code=>({code,name:names.of(code)}));for(const {code,name}of countries.sort((a,b)=>a.name.localeCompare(b.name))){const option=document.createElement('option');option.value=code;option.textContent=name;option.lang=getLanguage();$('country').append(option);}
async function fetchRecipes(){const base=await jsonFetch('/recipes.json?v=i18n-1');try{const r=await jsonFetch('/api/recipes');return [...new Map([...base,...r].map(x=>[x.id,x])).values()];}catch{return base;}}
function switchAccount(next){requestIdentity={owner:demoMode?null:next?.id||null};shopsRequest++;$('prices').replaceChildren();insights.resetPrices();care.reset();recipeCommunity.reset();communityAI.reset();personalAI.reset();administration.reset();adminOperations.reset();authResolved=true;user=next;accountBackup.reset();dataUi.reset();const suffix=demoMode?'-demo':next?'-user-'+next.id:'';KEY='offmenu-pantry-v1'+suffix;PRODUCTS='offmenu-products-v1'+suffix;RECIPES='offmenu-recipes-v1'+suffix;PROFILE='offmenu-profile-v1'+suffix;SELECTIONS='offmenu-selections-v1'+suffix;revision=Number(localStorage.getItem(KEY+'-revision')||0);dirty=localStorage.getItem(KEY+'-dirty')==='1';for(const id of ['logout','cloud-save','cloud-load'])$(id).hidden=!next||demoMode;$('auth-controls').hidden=!!next&&!recoveryMode; if(recoveryMode)$('new-password').hidden=false;setLocalizedText($('account-status'),next?t("Signed in as {v0}", {v0:(next.email||next.name||'member')}):t('Sign in to restore your pantry on another device.'));}
async function initAuth(){try{const callback=await handleAuthCallback();if(callback?.type==='invite'){inviteToken=callback.token;$('new-password').hidden=false;}if(callback?.type==='recovery'){recoveryMode=true;$('new-password').hidden=false;}const settings=await getSettings();$('auth-controls').hidden=false;$('signup').hidden=settings.disableSignup;for(const [provider,enabled]of Object.entries(settings.providers)){if(enabled&&provider!=='email'){const b=document.createElement('button');b.className='provider-button';b.innerHTML=providerMark(provider);const label=document.createElement('span');setLocalizedText(label,"Continue with {v0}{v1}",{v0:(provider[0].toUpperCase()),v1:(provider.slice(1))});b.append(label);b.onclick=()=>oauthLogin(provider);$('providers').append(b);}}switchAccount(await getUser());}catch{$('auth-controls').hidden=true;setLocalizedText($('account-status'),'Account setup pending. Guest pantry and offline recipes remain available.');}}
async function cloudRequest(method,body){if(demoMode)throw Error(t('Exit the demo to save your own kitchen.'));const response=await boundFetch('/api/state',{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw apiError(data,'Cloud operation failed.');return data;}
async function loadCloud(ask=true){const started=requestIdentity;const check=()=>{if(requestIdentity!==started)throw Error(t('Account changed. Retry from your current account.'));};const data=await cloudRequest('GET');check();if(data.state){if(ask&&!confirm(t('Replace this browser copy with the cloud save? Export local changes first.')))return;const state=data.state;const nextRecipes=validateRecipes([...new Map([...state.recipes,...await fetchRecipes()].map(r=>[r.id,r])).values()]);check();localStorage.setItem(KEY,JSON.stringify(state.inventory));localStorage.setItem(PRODUCTS,JSON.stringify(state.products));localStorage.setItem(RECIPES,JSON.stringify(state.recipes));localStorage.setItem(PROFILE,JSON.stringify(state.profile));localStorage.setItem(SELECTIONS,JSON.stringify(state.selections));lots=state.inventory;products=state.products;recipes=nextRecipes;localStorage.setItem(RECIPES,JSON.stringify(recipes));loadProfile();pantry();findMeals();}revision=data.revision;localStorage.setItem(KEY+'-revision',String(revision));dirty=false;localStorage.removeItem(KEY+'-dirty');if(syncReady&&data.state)autoSync.reset(data.state,data.revision);setLocalizedText($('sync-status'),data.state?t('Cloud copy restored.'):t('No cloud copy yet. Add items or import a backup, then save.'));}
$('cloud-load').onclick=()=>{if(sharing.active())return syncStatus('Return to your private kitchen before restoring its cloud copy.','pending');return loadCloud().catch(e=>setLocalizedText($('sync-status'),e.message));};
$('cloud-save').onclick=async()=>{if(sharing.active()){sharing.schedule();return;}try{saveProfile();const data=await cloudRequest('PUT',{revision,state:{inventory:lots,products,recipes,profile,selections}});revision=data.revision;localStorage.setItem(KEY+'-revision',String(revision));localStorage.removeItem(KEY+'-dirty');dirty=false;setLocalizedText($('sync-status'),'Saved to cloud. Automatic saving continues.');}catch(e){setLocalizedText($('sync-status'),e.message);}};
async function signedIn(next){demoMode=false;session=null;switchAccount(next);sharing.reset();loadProfile();lots=JSON.parse(localStorage.getItem(KEY)||'[]').map(validateLot);products=JSON.parse(localStorage.getItem(PRODUCTS)||'{}');recipes=validateRecipes(JSON.parse(localStorage.getItem(RECIPES)||'null')||await fetchRecipes());pantry();findMeals();connectivity();if(next&&!dirty&&!demoMode&&!localStorage.getItem(KEY+'-shared-session'))await loadCloud(false);else if(next) setLocalizedText($('sync-status'),'Unsaved local changes retained. Export or save before loading cloud data.');$('password').value='';$('account-dialog').close();if(next){await sharing.resume().catch(e=>syncStatus(e.message,'pending'));autoSync.schedule();openWorkspace();await access.checkConsent();}}
$('login').onclick=async()=>{try{await signedIn(await login($('email').value,$('password').value));}catch(e){setLocalizedText($('account-status'),e.message);}};
$('signup').onclick=async()=>{try{await signup($('email').value,$('password').value);const next=await getUser();if(next)await signedIn(next);else setLocalizedText($('account-status'),'Check your email to confirm your account.');$('password').value='';}catch(e){setLocalizedText($('account-status'),e.message);}};
$('recover').onclick=async()=>{try{await requestPasswordRecovery($('email').value);setLocalizedText($('account-status'),'Check your email for recovery instructions.');}catch(e){setLocalizedText($('account-status'),e.message);}};
$('new-password').onclick=async()=>{try{const next=inviteToken?await acceptInvite(inviteToken,$('password').value):await updateUser({password:$('password').value});inviteToken=null;recoveryMode=false;$('new-password').hidden=true;await signedIn(next);}catch(e){setLocalizedText($('account-status'),e.message);}};
$('logout').onclick=async()=>{try{await logout();await signedIn(null);}catch(e){setLocalizedText($('account-status'),e.message);}};


