function setMode(mode){selectedMode=mode;for(const name of ['shelf','shopping','waste']){$('mode-'+name).classList.toggle('selected',name===mode);$('mode-'+name).setAttribute('aria-pressed',String(name===mode));}setLocalizedText($('setup-help'),mode==='waste'?t('Choose the source location. Scan items you are discarding; review the removal receipt before the inventory changes.'):mode==='shelf'?t('Clear this shelf onto your bench. Its current inventory stays intact until you review and finish.'):t('Choose where these groceries will go. Scan one destination at a time, then add them to the items already there.'));}
