function completeScannerHandoff(x,already=false){pendingScannerImport=null;let cleanupFailed=false;try{sessionStorage.removeItem(KITCHEN_HANDOFF);}catch{cleanupFailed=true;}if(x.schema===PUBLIC_SCANNER_HANDOFF){msg(cleanupFailed?'Scanner draft saved; tab cleanup failed. Repeating this handoff will not add it again.':already?'This scanner handoff was already staged or completed.':'Published source items staged. Review each known quantity and ingredient, then confirm the existing final receipt.');return;}const ref=x.sourceObservationReference;msg(cleanupFailed?'The scanner item is saved. Browser cleanup failed; this handoff will not be added again.':already?'This scanner handoff is already saved.':'Retained source '+x.sourceId+' · '+(x.releaseId||'release unknown')+(ref.matchType==='representation-alias'?' · labelled '+ref.equivalence:'')+' · '+ref.disposition+' staged for review. Confirm quantity and ingredient before recipe matching. No nutrition or package amount inferred.');}
