function applyFeedbackSettings(){for(const key of ['sound','vibration','screen','light','speech'])$('feedback-'+key).checked=feedback[key];soundEnabled=feedback.sound;$('sound-toggle').setAttribute('aria-pressed',String(soundEnabled));setLocalizedText($('sound-toggle'),soundEnabled?t('♪ Sound on'):t('♪ Sound off'));$('feedback-vibration').disabled=typeof navigator.vibrate!=='function';setLocalizedText($('vibration-support'),typeof navigator.vibrate==='function'?t('A short pulse after each scan.'):t('Vibration is unavailable in this browser.'));$('feedback-speech').disabled=!('speechSynthesis' in window);setLocalizedText($('speech-support'),'speechSynthesis' in window?t('Hear the product name as it is identified.'):t('Speech is unavailable in this browser.'));configureLight();}
